INSERT INTO `wp_bookly_notifications` VALUES (1,'email','new_booking',1,'Notificación a los clientes acerca cita aprobado','Información de tu cita','Apreciado(a) {client_name}.\n\nEsta es la confirmación de la cita para {service_name}.\n\nTe estaremos esperando en {company_address} el {appointment_date} a las {appointment_time} .\n\nGracias por confiar en nosotros.\n\n{company_name}\n{company_phone}\n{company_website}',0,1,0,0,NULL,0,0,0,'{\"status\":\"approved\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),(2,'email','new_booking',1,'Notificación a un miembro del personal acerca cita aprobado','Información de nueva cita','Hola.\n\nTienes una nueva cita.\n\nServicio: {service_name}\nFecha: {appointment_date}\nHora: {appointment_time}\nNombre del cliente: {client_name}\nTeléfono del cliente: {client_phone}\nEmail del cliente: {client_email}',1,0,0,0,NULL,0,0,0,'{\"status\":\"approved\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),(3,'email','ca_status_changed',1,'Notificación a los clientes acerca cita cancelada','Cancelación de la reserva','Estimado/a {client_name}.\n\nHa cancelado su reserva de {service_name} el {appointment_date} a las {appointment_time}.\n\nGracias por escoger nuestra compañia.\n\n{company_name}\n{company_phone}\n{company_website}',0,1,0,0,NULL,0,0,0,'{\"status\":\"cancelled\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),(4,'email','ca_status_changed',1,'Notificación a un miembro del personal acerca cita cancelada','Cancelación de la reserva','Hola.\n\nLa siguiente reserva ha sido cancelada.\n\nServicio: {service_name}\nFecha: {appointment_date}\nHora: {appointment_time}\nNombre del cliente: {client_name}\nTeléfono del cliente: {client_phone}\nCorreo electrónico del cliente: {client_email}',1,0,0,0,NULL,0,0,0,'{\"status\":\"cancelled\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),(5,'email','ca_status_changed',1,'Notificación a los clientes acerca de la designación rechazada','Rechazo de reserva','Estimado {client_name}.\n\nSe ha rechazado su reserva de {service_name} el {appointment_date} en {appointment_time}.\n\nRazón: {cancellation_reason}\n\nGracias por escoger nuestra compañia.\n\n{company_name}\n{company_phone}\n{company_website}',0,1,0,0,NULL,0,0,0,'{\"status\":\"rejected\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),(6,'email','ca_status_changed',1,'Notificación a un miembro del personal acerca de la designación rechazada','Rechazo de reserva','Hola.\n\nLa siguiente reserva ha sido rechazada.\n\nRazón: {cancellation_reason}\n\nServicio: {service_name}\nFecha: {appointment_date}\nTiempo: {appointment_time}\nNombre del cliente: {client_name}\nTeléfono del cliente: {client_phone}\nCorreo electrónico del cliente: {client_email}',1,0,0,0,NULL,0,0,0,'{\"status\":\"rejected\",\"payment_statuses\":[\"completed\"],\"option\":2,\"services\":{\"any\":\"any\",\"ids\":[]},\"offset_hours\":2,\"perform\":\"before\",\"at_hour\":9,\"before_at_hour\":18,\"offset_before_hours\":-24,\"offset_bidirectional_hours\":0}'),(7,'sms','new_booking',1,'Notificación a los clientes acerca cita aprobad