--
-- Table structure for table `wp_bookly_sms_log`
--

DROP TABLE IF EXISTS `wp_bookly_sms_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_bookly_sms_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `message` varchar(3072) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
